    MOD = 998244353

    SZ = 1 << N

    # Precompute transitions: trans[mask][char_index] -> new_mask
    trans = [[0] * 26 for _ in range(SZ)]
    for mask in range(SZ):
        dp = [0] * (N + 1)
        for i in range(1, N + 1):
            dp[i] = dp[i - 1] + ((mask >> (i - 1)) & 1)
        for ci in range(26):
            c = chr(ord('a') + ci)
            new_dp = [0] * (N + 1)
            for i in range(1, N + 1):
                best = new_dp[i - 1]
                if dp[i] > best:
                    best = dp[i]
                if S[i - 1] == c:
                    v = dp[i - 1] + 1
                    if v > best:
                        best = v
                new_dp[i] = best
            nm = 0
            for i in range(1, N + 1):
                if new_dp[i] != new_dp[i - 1]:
                    nm |= 1 << (i - 1)
            trans[mask][ci] = nm

    # DP over positions of T
    cur = [0] * SZ
    cur[0] = 1
    for _ in range(M):
        nxt = [0] * SZ
        for mask in range(SZ):
            v = cur[mask]
            if v == 0:
