            row = trans[mask]
            for ci in range(26):
                t = row[ci]
                nxt[t] += v
                if nxt[t] >= MOD:
                    nxt[t] -= MOD
        cur = nxt

    # Group results by LCS length (= popcount of final mask)
    ans = [0] * (N + 1)
    for mask in range(SZ):
        v = cur[mask]
        if v:
            k = bin(mask).count('1')
            ans[k] += v
            if ans[k] >= MOD:
                ans[k] -= MOD

    print(' '.join(str(x % MOD) for x in ans))

