    N = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1

    groups = {1: [], 2: [], 3: []}
    for _ in range(N):
        v = int(data[idx]); idx += 1
        a = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        groups[v].append((a, c))

    bests = []
    for v in [1, 2, 3]:
        dp = [0] * (X + 1)
        for a, c in groups[v]:
            for j in range(X, c - 1, -1):
                val = dp[j - c] + a
                if val > dp[j]:
                    dp[j] = val
        for j in range(1, X + 1):
            if dp[j] < dp[j - 1]:
                dp[j] = dp[j - 1]
        bests.append(dp)

    def min_cal(best, M):
        lo, hi = 0, X
        while lo < hi:
            mid = (lo + hi) // 2
            if best[mid] >= M:
                hi = mid
            else:
                lo = mid + 1
        if best[lo] >= M:
            return lo
        return None

    lo, hi = 0, 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        total = 0
        feasible = True
        for b in bests:
            mc = min_cal(b, mid)
            if mc is None:
                feasible = False
                break
            total += mc
        if feasible and total <= X:
            lo = mid
        else:
