import heapq

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    X = int(next(it))

    out = [[] for _ in range(N + 1)]   # original outgoing edges
    rev = [[] for _ in range(N + 1)]   # original incoming edges (for layer 1)

    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        out[u].append(v)
        rev[v].append(u)

    INF = 10 ** 30
    dist0 = [INF] * (N + 1)   # parity 0
    dist1 = [INF] * (N + 1)   # parity 1
    dist0[1] = 0

    pq = [(0, 1, 0)]          # (distance, vertex, parity)

    while pq:
        d, v, p = heapq.heappop(pq)
        if p == 0:
            if d != dist0[v]:
                continue
        else:
            if d != dist1[v]:
                continue

        # move along an edge (cost 1)
        neigh = out[v] if p == 0 else rev[v]
        nd = d + 1
        for u in neigh:
            if p == 0:
                if nd < dist0[u]:
                    dist0[u] = nd
                    heapq.heappush(pq, (nd, u, 0))
            else:
                if nd < dist1[u]:
                    dist1[u] = nd
                    heapq.heappush(pq, (nd, u, 1))

        # reverse all edges (cost X)
        np = 1 - p
        nd = d + X
        if np == 0:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(pq, (nd, v, 0))
        else:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(pq, (nd, v, 1))

    ans = min(dist0[N], dist1[N])
    print(ans)


if __name__ == "__main__":
    solve()

