def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1]
    T = data[2]

    # Step 1: Check consistency of mapping
    target = {}
    for i in range(N):
        s, t = S[i], T[i]
        if s in target:
            if target[s] != t:
                print(-1)
                return
        else:
            target[s] = t

    # Step 2: Build directed graph for non-self-mappings
    nxt = {}
    for c, t in target.items():
        if c != t:
            nxt[c] = t

    if not nxt:
        print(0)
        return

    # Step 3: Build undirected graph for connected components
    undirected = defaultdict(set)
    for c, t in nxt.items():
        undirected[c].add(t)
        undirected[t].add(c)

    visited = set()
    total = 0

    for start in list(undirected.keys()):
        if start in visited:
            continue

        # BFS to find connected component
        component = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in component:
                continue
            component.add(node)
            for nb in undirected[node]:
                if nb not in component:
                    stack.append(nb)
        visited.update(component)

        # Count directed edges in this component
        edges = sum(1 for c in component if c in nxt)

        # Detect cycle by following directed edges
        has_cycle = False
        for node in component:
            if node not in nxt:
                continue
            seen = set()
            cur = node
            while cur in nxt:
                if cur in seen:
                    has_cycle = True
                    break
                seen.add(cur)
                cur = nxt[cur]
            if has_cycle:
                break

        if has_cycle:
            total += edges + 1
        else:
            total += edges

    print(total)

