from collections import deque

def main():
    data = sys.stdin.read().splitlines()
    N = int(data[0])
    grid = data[1:N+1]

    in_by_label = [[[] for _ in range(26)] for _ in range(N)]
    out_by_label = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            ch = grid[i][j]
            if ch != '-':
                ci = ord(ch) - ord('a')
                out_by_label[i][ci].append(j)
                in_by_label[j][ci].append(i)

    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    queue = deque()

    for u in range(N):
        dist[u][u] = 0
        queue.append((u, u))

    for i in range(N):
        for ci in range(26):
            for j in out_by_label[i][ci]:
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    queue.append((i, j))

    while queue:
        u, v = queue.popleft()
        d = dist[u][v]
        nd = d + 2
        for ci in range(26):
            ins = in_by_label[u][ci]
            outs = out_by_label[v][ci]
            if not ins or not outs:
                continue
            for u_prev in ins:
                for v_next in outs:
                    if dist[u_prev][v_next] > nd:
                        dist[u_prev][v_next] = nd
                        queue.append((u_prev, v_next))

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            if dist[i][j] == INF:
                row.append('-1')
            else:
                row.append(str(int(dist[i][j])))
        out_lines.append(' '.join(row))

    sys.stdout.write('\n'.join(out_lines) + '\n')

