    idx = 0
    N = int(input_data[idx]); idx += 1

    dice = []
    for _ in range(N):
        K = int(input_data[idx]); idx += 1
        faces = []
        for _ in range(K):
            faces.append(int(input_data[idx])); idx += 1
        dice.append((K, Counter(faces)))

    max_prob = 0.0
    for i in range(N):
        Ki, ci = dice[i]
        for j in range(i + 1, N):
            Kj, cj = dice[j]
            prob = 0.0
            # Iterate over the smaller counter for efficiency
            if len(ci) <= len(cj):
                for v in ci:
                    cnt_j = cj.get(v, 0)
                    if cnt_j:
                        prob += (ci[v] / Ki) * (cnt_j / Kj)
            else:
                for v in cj:
                    cnt_i = ci.get(v, 0)
                    if cnt_i:
                        prob += (cnt_i / Ki) * (cj[v] / Kj)
            if prob > max_prob:
                max_prob = prob

    print("{:.15f}".format(max_prob))

